//! `iron_ts_rt`: the runtime that code generated by `iron_ts` calls into.
//!
//! # Memory: a precise, non-moving mark-sweep collector
//!
//! Every script object (struct, array, string, closure) is a GC object with an 8-byte header.
//! The heap is per thread. Small blocks (up to 512 bytes) come from 1 MiB chunks and go back to
//! size-class free lists when swept; larger ones use the system allocator. Nothing moves, so a
//! pointer the host holds stays valid while the object is reachable.
//!
//! Layouts (all 8-byte slots, little endian):
//! - struct: `[header = struct id + 1][field 0][field 1]...`
//! - array: `Array { header, len, cap, data }`; `data` is a separate block owned by the array
//!   (`cap` 8-byte slots, or `cap` bytes for `Uint8Array`). `HDR_ARRAY_PTR` arrays hold pointers.
//! - string: `Str { header, .. }` with its WTF-8 bytes inline (`string.rs`); closure: `Closure { header, func, env }`
//!   (`env` is host memory and is not traced).
//!
//! The header's top bit is the mark bit. Which struct slots hold pointers comes from a table the
//! generated `ts_init` registers (`ts_rt_register_struct`).
//!
//! # Roots
//!
//! 1. **Shadow stack.** A generated function that holds pointers pushes a `Frame` (a stack
//!    slot of its own) with one slot per pointer local plus spill temporaries, and mirrors every
//!    pointer assignment into it. The collector walks the frame list. Registers and Cranelift's
//!    spill slots are never scanned.
//! 2. **Globals.** Script globals register their address (`ts_rt_add_global_root`).
//! 3. **Host handles.** Rust code that keeps script pointers across calls into generated code
//!    roots them (`ts_rt_root_add` / `ts_rt_root_remove`).
//!
//! # When it runs
//!
//! Only at allocations made by *generated* code (`ts_rt_obj_new_gc`, `ts_rt_arr_new_gc`,
//! `ts_rt_bytes_new_gc`), when the bytes allocated since the last collection pass a threshold
//! (the larger of 512 KiB and the live size), or on every allocation in stress mode
//! (`ts_rt_gc_stress`), or when the host calls `ts_rt_gc_collect`. The host-facing constructors
//! never collect, so Rust can build a graph from unrooted pieces and root it afterwards.
//! `ts_rt_arr_push` never collects either (it only grows the array).

use std::alloc::{Layout, alloc, alloc_zeroed, dealloc};
use std::cell::UnsafeCell;
use std::sync::atomic::{AtomicU64, Ordering};

const CHUNK: usize = 1 << 20;
/// Blocks up to this many 16-byte granules come from chunks and free lists.
const MAX_CLASS: usize = 32;
const MARK: u64 = 1 << 63;
/// A header is `mark(1) | heap id(31) | kind(32)`. The heap id keeps one thread's collector away
/// from objects of another thread's heap that it finds through a shared global slot.
const KIND_MASK: u64 = 0xFFFF_FFFF;
static NEXT_HEAP: AtomicU64 = AtomicU64::new(1);

/// The kind part of an object's header (`HDR_*` or a struct id + 1), without mark and heap id.
pub fn header_kind(header: u64) -> u64 {
    header & KIND_MASK
}

fn header_heap(header: u64) -> u64 {
    (header >> 32) & 0x7FFF_FFFF
}
const MIN_THRESHOLD: usize = 512 << 10;

/// Header words of the non-struct objects. Struct headers are `struct id + 1`, far below these.
pub const HDR_ARRAY: u64 = 0xA11A_0001;
pub const HDR_BYTES: u64 = 0xA11A_0002;
pub const HDR_STR: u64 = 0xA11A_0003;
pub const HDR_CLOSURE: u64 = 0xA11A_0004;
/// An array whose elements are pointers (traced).
pub const HDR_ARRAY_PTR: u64 = 0xA11A_0005;
/// A captured variable's box: `{header, value}`; `HDR_CELL_PTR` when the value is a pointer.
pub const HDR_CELL: u64 = 0xA11A_0006;
pub const HDR_CELL_PTR: u64 = 0xA11A_0007;
/// A closure made by generated code: like `HDR_CLOSURE`, but `env` is a GC object and is traced.
pub const HDR_CLOSURE_ENV: u64 = 0xA11A_0008;
/// A `Map` or `Set` (`map.rs`): entries and an index in raw blocks; keys and values are traced.
pub const HDR_MAP: u64 = 0xA11A_0009;
/// A `BigInt`: sign, byte count and magnitude bytes, no children.
pub const HDR_BIGINT: u64 = 0xA11A_000A;
/// A typed array over another object's bytes (`typed.rs`): `{header, len, cap, data, owner}`.
pub const HDR_VIEW: u64 = 0xA11A_000C;
/// A coroutine (a generator's body on its own stack): see `coro.rs`.
pub const HDR_CORO: u64 = 0xA11A_000B;

/// One function activation's pointer slots; `n` slots follow in memory.
#[repr(C)]
pub struct Frame {
    prev: *mut Frame,
    n: u64,
}

struct Heap {
    id: u64,
    cur: *mut u8,
    end: *mut u8,
    free: [Vec<*mut u8>; MAX_CLASS + 1],
    /// Every GC object and its size in bytes.
    objs: Vec<(*mut u8, u32)>,
    /// `(field count, pointer-slot mask)` per struct, indexed by header - 1.
    structs: Vec<(u32, u64)>,
    host_roots: Vec<*mut u8>,
    /// Values a runtime call holds while it collects (a closure's environment, a new cell's value).
    temps: Vec<*mut u8>,
    global_roots: Vec<*mut *mut u8>,
    top: *mut Frame,
    since_gc: usize,
    threshold: usize,
    live: usize,
    total: usize,
    collections: u64,
    stress: bool,
    enabled: bool,
    /// The exception being thrown (an object), or null. A root.
    exc: *mut u8,
    /// Microtasks and timers (their closures are roots).
    events: event::Events,
}

thread_local! {
    static HEAP: UnsafeCell<Heap> = const { UnsafeCell::new(Heap {
        id: 0,
        cur: std::ptr::null_mut(),
        end: std::ptr::null_mut(),
        free: [const { Vec::new() }; MAX_CLASS + 1],
        objs: Vec::new(),
        structs: Vec::new(),
        host_roots: Vec::new(),
        temps: Vec::new(),
        global_roots: Vec::new(),
        top: std::ptr::null_mut(),
        since_gc: 0,
        threshold: MIN_THRESHOLD,
        live: 0,
        total: 0,
        collections: 0,
        stress: false,
        enabled: true,
        exc: std::ptr::null_mut(),
        events: event::Events::new(),
    }) };
}

/// Runs `f` on this thread's heap. `f` must not call back into a `with_heap` function.
fn with_heap<T>(f: impl FnOnce(&mut Heap) -> T) -> T {
    // SAFETY: thread local; callers do not nest.
    HEAP.with(|h| {
        let h = unsafe { &mut *h.get() };
        if h.id == 0 {
            h.id = NEXT_HEAP.fetch_add(1, Ordering::Relaxed);
        }
        f(h)
    })
}

// ---- raw blocks ----

fn raw_alloc(h: &mut Heap, size: usize, zero: bool) -> *mut u8 {
    let class = size.max(1).div_ceil(16);
    h.since_gc += class * 16;
    h.total += class * 16;
    if class <= MAX_CLASS {
        if let Some(p) = h.free[class].pop() {
            if zero {
                // SAFETY: a block of `class * 16` bytes.
                unsafe { std::ptr::write_bytes(p, 0, class * 16) };
            }
            return p;
        }
        let need = class * 16;
        if (h.end as usize) - (h.cur as usize) < need || h.cur.is_null() {
            // SAFETY: valid non-zero layout.
            let c = unsafe { alloc_zeroed(Layout::from_size_align(CHUNK, 16).unwrap()) };
            assert!(!c.is_null(), "out of memory");
            h.cur = c;
            // SAFETY: within the chunk.
            h.end = unsafe { c.add(CHUNK) };
        }
        let p = h.cur;
        // SAFETY: `need` bytes are left in the chunk. Fresh chunk memory is already zero.
        h.cur = unsafe { p.add(need) };
        p
    } else {
        let layout = Layout::from_size_align(class * 16, 16).unwrap();
        // SAFETY: non-zero layout.
        let p = unsafe {
            if zero {
                alloc_zeroed(layout)
            } else {
                alloc(layout)
            }
        };
        assert!(!p.is_null(), "out of memory");
        p
    }
}

fn raw_free(h: &mut Heap, p: *mut u8, size: usize) {
    let class = size.max(1).div_ceil(16);
    if h.stress {
        // SAFETY: the block is `class * 16` bytes; poison makes a use after free loud.
        unsafe { std::ptr::write_bytes(p, 0xDD, class * 16) };
    }
    if class <= MAX_CLASS {
        h.free[class].push(p);
    } else {
        // SAFETY: allocated with this layout in `raw_alloc`.
        unsafe { dealloc(p, Layout::from_size_align(class * 16, 16).unwrap()) };
    }
}

// ---- objects ----

fn new_obj(h: &mut Heap, header: u64, size: usize) -> *mut u8 {
    let p = raw_alloc(h, size, true);
    // SAFETY: at least 16 bytes.
    unsafe { *(p as *mut u64) = header | (h.id << 32) };
    h.objs.push((p, size as u32));
    p
}

fn maybe_collect(h: &mut Heap) {
    if h.stress || (h.enabled && h.since_gc >= h.threshold) {
        collect(h);
    }
}

/// A zeroed struct object of `size` bytes (header included) with `header` (struct id + 1).
/// Never collects: for the host.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_obj_new(header: u64, size: usize) -> *mut u8 {
    with_heap(|h| new_obj(h, header, size))
}

/// Like `ts_rt_obj_new`, but may collect first. Called by generated code, where every live
/// pointer is rooted.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_obj_new_gc(header: u64, size: usize) -> *mut u8 {
    with_heap(|h| {
        maybe_collect(h);
        new_obj(h, header, size)
    })
}

/// A shallow copy of a struct object, keeping its own (possibly derived) class.
///
/// # Safety
/// `p` must be a live struct object.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ts_rt_obj_copy_gc(p: *const u8) -> *mut u8 {
    // SAFETY: by contract; the source is copied before it can be collected (it is rooted by the
    // caller's frame while this runs).
    unsafe {
        let header = header_kind(*(p as *const u64));
        let fields = with_heap(|h| {
            maybe_collect(h);
            h.structs[header as usize - 1].0 as usize
        });
        let size = 8 + fields * 8;
        let out = with_heap(|h| new_obj(h, header, size));
        std::ptr::copy_nonoverlapping(p.add(8), out.add(8), fields * 8);
        out
    }
}

#[repr(C)]
pub struct Array {
    pub header: u64,
    pub len: i64,
    pub cap: i64,
    pub data: *mut u8,
}

fn new_array(h: &mut Heap, cap: i64, ptr_elems: bool) -> *mut Array {
    let a = new_obj(
        h,
        if ptr_elems { HDR_ARRAY_PTR } else { HDR_ARRAY },
        std::mem::size_of::<Array>(),
    ) as *mut Array;
    let cap = cap.max(0);
    if cap > 0 {
        let d = raw_alloc(h, cap as usize * 8, false);
        // SAFETY: just allocated.
        unsafe {
            (*a).cap = cap;
            (*a).data = d;
        }
    }
    a
}

/// A new empty array with room for `cap` elements; `ptr_elems` (1) if they are pointers. Never collects.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_arr_new(cap: i64, ptr_elems: i64) -> *mut Array {
    with_heap(|h| new_array(h, cap, ptr_elems != 0))
}

#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_arr_new_gc(cap: i64, ptr_elems: i64) -> *mut Array {
    with_heap(|h| {
        maybe_collect(h);
        new_array(h, cap, ptr_elems != 0)
    })
}

/// Appends one 8-byte slot (a number's bits, a pointer, a bool, a tag). Never collects.
///
/// # Safety
/// `a` must be an array from `ts_rt_arr_new`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ts_rt_arr_push(a: *mut Array, v: u64) {
    // SAFETY: `a` is an array.
    unsafe {
        let arr = &mut *a;
        if arr.len == arr.cap {
            let ncap = (arr.cap * 2).max(4);
            with_heap(|h| {
                let nd = raw_alloc(h, ncap as usize * 8, false);
                if arr.len > 0 {
                    std::ptr::copy_nonoverlapping(arr.data, nd, arr.len as usize * 8);
                }
                if arr.cap > 0 {
                    raw_free(h, arr.data, arr.cap as usize * 8);
                }
                arr.data = nd;
            });
            arr.cap = ncap;
        }
        *(arr.data as *mut u64).add(arr.len as usize) = v;
        arr.len += 1;
    }
}

fn new_bytes(h: &mut Heap, len: i64) -> *mut Array {
    let a = new_obj(h, HDR_BYTES, std::mem::size_of::<Array>()) as *mut Array;
    let len = len.max(0);
    let d = raw_alloc(h, len as usize, true);
    // SAFETY: just allocated.
    unsafe {
        (*a).len = len;
        (*a).cap = len;
        (*a).data = d;
    }
    a
}

#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_bytes_new(len: i64) -> *mut Array {
    with_heap(|h| new_bytes(h, len))
}

#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_bytes_new_gc(len: i64) -> *mut Array {
    with_heap(|h| {
        maybe_collect(h);
        new_bytes(h, len)
    })
}

/// `bytes.fill(value, start, end)` with JS clamping to the length.
///
/// # Safety
/// `a` must be a byte array from `ts_rt_bytes_new`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ts_rt_bytes_fill(a: *mut Array, value: i64, start: i64, end: i64) {
    // SAFETY: `a` is a byte array.
    unsafe {
        let arr = &*a;
        let s = start.clamp(0, arr.len);
        let e = end.clamp(s, arr.len);
        std::ptr::write_bytes(arr.data.add(s as usize), value as u8, (e - s) as usize);
    }
}

// ---- collection ----

unsafe fn mark_ptr(p: *mut u8, heap: u64, stack: &mut Vec<*mut u8>) {
    if p.is_null() {
        return;
    }
    let hd = p as *mut u64;
    // SAFETY: `p` is a GC object (a root or a traced slot).
    unsafe {
        // Another thread's object (reached through a global shared between threads): not ours.
        if *hd & MARK != 0 || header_heap(*hd) != heap {
            return;
        }
        *hd |= MARK;
    }
    stack.push(p);
}

fn collect(h: &mut Heap) {
    let heap = h.id;
    let mut stack: Vec<*mut u8> = Vec::new();
    // SAFETY: roots are GC objects or null; slots of live frames are pointers or zero.
    unsafe {
        for &r in h
            .host_roots
            .iter()
            .chain(h.temps.iter())
            .chain(std::iter::once(&h.exc))
            .chain(h.events.roots())
        {
            mark_ptr(r, heap, &mut stack);
        }
        for &g in &h.global_roots {
            mark_ptr(*g, heap, &mut stack);
        }
        let mut f = h.top;
        while !f.is_null() {
            let slots = (f as *mut u8).add(std::mem::size_of::<Frame>()) as *mut *mut u8;
            for i in 0..(*f).n as usize {
                mark_ptr(*slots.add(i), heap, &mut stack);
            }
            f = (*f).prev;
        }
        while let Some(p) = stack.pop() {
            let hdr = header_kind(*(p as *const u64));
            match hdr {
                HDR_ARRAY_PTR => {
                    let a = &*(p as *const Array);
                    for i in 0..a.len as usize {
                        mark_ptr(*(a.data as *const *mut u8).add(i), heap, &mut stack);
                    }
                }
                HDR_CELL_PTR => mark_ptr(*(p.add(8) as *const *mut u8), heap, &mut stack),
                HDR_MAP => {
                    let mut found = Vec::new();
                    (*(p as *const MapObj)).for_each_pointer(|q| found.push(q));
                    for q in found {
                        mark_ptr(q, heap, &mut stack);
                    }
                }
                HDR_CLOSURE_ENV => mark_ptr(*(p.add(16) as *const *mut u8), heap, &mut stack),
                HDR_VIEW => mark_ptr(*(p.add(32) as *const *mut u8), heap, &mut stack),
                HDR_CORO => {
                    let mut found = Vec::new();
                    coro::for_each_pointer(p as *const coro::Coro, |q| found.push(q));
                    for q in found {
                        mark_ptr(q, heap, &mut stack);
                    }
                }
                HDR_ARRAY | HDR_BYTES | HDR_STR | HDR_CLOSURE | HDR_CELL | HDR_BIGINT => {}
                id => {
                    let (n, mask) = *h.structs.get(id as usize - 1).unwrap_or_else(|| {
                        panic!("struct header {id} was never registered (call ts_init)")
                    });
                    for i in 0..n as usize {
                        if mask >> i & 1 != 0 {
                            mark_ptr(*(p.add(8 + 8 * i) as *const *mut u8), heap, &mut stack);
                        }
                    }
                }
            }
        }
    }
    // Sweep.
    let objs = std::mem::take(&mut h.objs);
    let mut keep = Vec::with_capacity(objs.len());
    let mut live = 0usize;
    for (p, size) in objs {
        // SAFETY: `p` is a GC object.
        unsafe {
            let hd = p as *mut u64;
            if *hd & MARK != 0 {
                *hd &= !MARK;
                live += size as usize;
                match header_kind(*hd) {
                    HDR_ARRAY | HDR_ARRAY_PTR => {
                        live += (*(p as *const Array)).cap.max(0) as usize * 8
                    }
                    HDR_BYTES => live += (*(p as *const Array)).cap.max(0) as usize,
                    HDR_MAP => {
                        let (e, i) = (*(p as *const MapObj)).blocks();
                        live += e + i;
                    }
                    _ => {}
                }
                keep.push((p, size));
                continue;
            }
            match header_kind(*hd) {
                HDR_ARRAY | HDR_ARRAY_PTR => {
                    let a = &*(p as *const Array);
                    if a.cap > 0 {
                        raw_free(h, a.data, a.cap as usize * 8);
                    }
                }
                HDR_BYTES => {
                    let a = &*(p as *const Array);
                    raw_free(h, a.data, a.cap.max(1) as usize);
                }
                HDR_MAP => (*(p as *mut MapObj)).free_blocks(h),
                HDR_CORO => coro::free(p as *mut coro::Coro),
                _ => {}
            }
        }
        raw_free(h, p, size as usize);
    }
    h.objs = keep;
    h.live = live;
    h.since_gc = 0;
    h.threshold = MIN_THRESHOLD.max(live);
    h.collections += 1;
}

/// `throw`: records the exception (an object) and returns; the compiled code finds it with
/// `ts_rt_exc_pending` after each call that can throw and unwinds by returning.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_throw(p: *mut u8) {
    with_heap(|h| h.exc = p);
}

/// Is an exception being thrown on this thread?
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_exc_pending() -> bool {
    with_heap(|h| !h.exc.is_null())
}

/// Takes the exception (a `catch`), clearing it. A host calls this after a call into compiled
/// code that left one pending.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_exc_take() -> *mut u8 {
    with_heap(|h| std::mem::replace(&mut h.exc, std::ptr::null_mut()))
}

/// Collects now. Every script pointer the host still needs must be rooted.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_gc_collect() {
    with_heap(collect);
}

/// Stress mode: collect at every allocation made by generated code, and poison freed memory.
/// Finds missing roots: a pointer that should have been rooted reads back as `0xDD...`.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_gc_stress(on: bool) {
    with_heap(|h| h.stress = on);
}

/// Turns automatic collection on or off (host calls to `ts_rt_gc_collect` always work).
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_gc_enable(on: bool) {
    with_heap(|h| h.enabled = on);
}

#[derive(Clone, Copy, Debug, Default)]
pub struct GcStats {
    pub collections: u64,
    /// Bytes of GC objects, array data included, that survived the last collection.
    pub live_bytes: usize,
    /// Bytes that may be handed out before the next automatic collection, from now.
    pub next_collection_at: usize,
    pub objects: usize,
    /// Bytes handed out in total, reused blocks included.
    pub allocated_bytes: usize,
}

pub fn gc_stats() -> GcStats {
    with_heap(|h| GcStats {
        collections: h.collections,
        live_bytes: h.live,
        next_collection_at: h.threshold.saturating_sub(h.since_gc),
        objects: h.objs.len(),
        allocated_bytes: h.total,
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_allocated() -> usize {
    with_heap(|h| h.total)
}

// ---- registration and roots ----

/// Registers which of a struct's `nfields` slots hold pointers (bit i of `mask`). `header` is the
/// struct id + 1.
/// `ts_rt_register_struct` with the collision reported instead of aborting.
pub fn register_struct(header: u64, nfields: u32, mask: u64) -> Result<(), String> {
    with_heap(|h| {
        let i = header as usize - 1;
        if h.structs.len() <= i {
            h.structs.resize(i + 1, (0, 0));
        }
        let new = (nfields, mask);
        if h.structs[i] != (0, 0) && h.structs[i] != new {
            return Err(format!(
                "struct id {header} collides: registered as {:?}, now {new:?} (give each module its own struct base)",
                h.structs[i]
            ));
        }
        h.structs[i] = new;
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_register_struct(header: u64, nfields: u32, mask: u64) {
    // A collision means two modules would trace each other's objects wrongly: stop.
    if let Err(e) = register_struct(header, nfields, mask) {
        eprintln!("{e}");
        std::process::abort();
    }
}

/// Registers the address of a global's pointer slot as a root.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_add_global_root(slot: *mut *mut u8) {
    with_heap(|h| {
        if !h.global_roots.contains(&slot) {
            h.global_roots.push(slot);
        }
    });
}

/// Roots a pointer for the host; returns a handle for `ts_rt_root_remove`.
#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_root_add(p: *mut u8) -> usize {
    with_heap(|h| match h.host_roots.iter().position(|r| r.is_null()) {
        Some(i) => {
            h.host_roots[i] = p;
            i
        }
        None => {
            h.host_roots.push(p);
            h.host_roots.len() - 1
        }
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_root_remove(handle: usize) {
    with_heap(|h| h.host_roots[handle] = std::ptr::null_mut());
}

/// Links a function's frame (`n` pointer slots after the two header words) onto the shadow stack.
///
/// # Safety
/// `f` must point to `16 + 8 * n` writable bytes that stay valid until the matching pop.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ts_rt_frame_push(f: *mut Frame, n: u64) {
    with_heap(|h| {
        // SAFETY: per the contract above.
        unsafe {
            (*f).prev = h.top;
            (*f).n = n;
            std::ptr::write_bytes(
                (f as *mut u8).add(std::mem::size_of::<Frame>()),
                0,
                n as usize * 8,
            );
        }
        h.top = f;
    });
}

#[unsafe(no_mangle)]
pub extern "C" fn ts_rt_frame_pop() {
    // SAFETY: pops pair with pushes.
    with_heap(|h| h.top = unsafe { (*h.top).prev });
}

