macro_rules! libm1 {
    ($($name:ident => $f:ident),* $(,)?) => {
        $(
            #[unsafe(no_mangle)]
            pub extern "C" fn $name(a: f64) -> f64 {
                a.$f()
            }
        )*
    };
}

