#[cfg(test)]
mod tests {
    use super::*;

    // M9-TS-17a
    #[test]
    fn arrays_grow_and_keep_their_values() {
        let a = ts_rt_arr_new(0, 0);
        for i in 0..100u64 {
            unsafe { ts_rt_arr_push(a, i * 3) };
        }
        let a = unsafe { &*a };
        assert_eq!(a.len(), 100);
        assert_eq!(unsafe { a.get::<u64>(99) }, 297);
    }

    // M9-TS-17b
    #[test]
    fn strings_concat_and_compare() {
        let a = unsafe { ts_rt_str_new(b"zom".as_ptr(), 3) };
        let b = unsafe { ts_rt_str_new(b"bie".as_ptr(), 3) };
        let c = unsafe { ts_rt_str_concat(a, b) };
        let d = unsafe { ts_rt_str_new(b"zombie".as_ptr(), 6) };
        assert!(unsafe { ts_rt_str_eq(c, d) });
        assert!(!unsafe { ts_rt_str_eq(a, b) });
    }

    // M9-TS-17c
    #[test]
    fn byte_fill_clamps_to_the_length() {
        let a = ts_rt_bytes_new(8);
        unsafe { ts_rt_bytes_fill(a, 1, 6, 100) };
        assert_eq!(unsafe { (*a).bytes() }, &[0, 0, 0, 0, 0, 0, 1, 1]);
    }

    // M9-TS-20
    #[test]
    fn unreachable_objects_are_freed_and_their_blocks_reused() {
        ts_rt_gc_collect();
        let before = gc_stats().objects;
        let garbage: Vec<_> = (0..10).map(|_| ts_rt_arr_new(4, 0)).collect();
        assert_eq!(gc_stats().objects, before + 10);
        ts_rt_gc_collect();
        assert_eq!(gc_stats().objects, before);
        let again = ts_rt_arr_new(4, 0);
        assert!(
            garbage.contains(&again),
            "a swept block is handed out again"
        );
    }

    // M9-TS-21
    #[test]
    fn host_roots_and_what_they_reach_survive() {
        // A struct (id 1) with one pointer slot.
        ts_rt_register_struct(1, 1, 1);
        let outer = ts_rt_obj_new(1, 16) as *mut *mut u8;
        let inner = ts_rt_arr_new(2, 0);
        unsafe { *outer.add(1) = inner as *mut u8 };
        let h = ts_rt_root_add(outer as *mut u8);
        ts_rt_gc_stress(true);
        ts_rt_gc_collect();
        let objs = gc_stats().objects;
        assert!(objs >= 2);
        assert_eq!(unsafe { header_kind((*inner).header) }, HDR_ARRAY);
        ts_rt_root_remove(h);
        ts_rt_gc_collect();
        assert_eq!(gc_stats().objects, objs - 2);
        ts_rt_gc_stress(false);
    }

    // M9-TS-22
    #[test]
    fn pointer_arrays_are_traced_and_shadow_stack_slots_are_roots() {
        let list = ts_rt_arr_new(0, 1);
        let item = ts_rt_arr_new(1, 0);
        unsafe { ts_rt_arr_push(list, item as u64) };
        // A frame with one slot holding `list`.
        let mut frame = [0u64; 3];
        let fp = frame.as_mut_ptr();
        unsafe {
            ts_rt_frame_push(fp as *mut Frame, 1);
            *fp.add(2) = list as u64;
        }
        ts_rt_gc_stress(true);
        ts_rt_gc_collect();
        assert_eq!(
            unsafe { header_kind((*item).header) },
            HDR_ARRAY,
            "reached through the array"
        );
        ts_rt_frame_pop();
        let before = gc_stats().objects;
        ts_rt_gc_collect();
        assert_eq!(
            gc_stats().objects,
            before - 2,
            "the frame is gone, so are its objects"
        );
        ts_rt_gc_stress(false);
    }

    // M9-TS-31
    //
    // Heaps are per thread but a module's globals are shared, so one thread's collector can find
    // a pointer into another thread's heap in a global slot. It must not touch such an object:
    // setting the other heap's mark bit would make that heap skip the object (and so its children)
    // at its next collection.
    #[test]
    fn a_collector_leaves_objects_of_another_threads_heap_alone() {
        ts_rt_register_struct(1, 1, 1);
        let outer = ts_rt_obj_new(1, 16) as *mut *mut u8;
        let first = ts_rt_arr_new(1, 0);
        unsafe { *outer.add(1) = first as *mut u8 };
        let h = ts_rt_root_add(outer as *mut u8);
        let addr = outer as usize;
        std::thread::spawn(move || {
            ts_rt_register_struct(1, 1, 1);
            let mut slot = addr as *mut u8;
            ts_rt_add_global_root(&mut slot);
            ts_rt_gc_collect();
        })
        .join()
        .unwrap();
        // Give `outer` a new child; if the other thread left a stale mark, we skip it.
        let second = ts_rt_arr_new(1, 0);
        unsafe { *outer.add(1) = second as *mut u8 };
        ts_rt_gc_stress(true);
        ts_rt_gc_collect();
        assert_eq!(
            unsafe { header_kind((*second).header) },
            HDR_ARRAY,
            "the new child was freed"
        );
        ts_rt_gc_stress(false);
        ts_rt_root_remove(h);
    }

    // M9-TS-32
    #[test]
    fn array_data_counts_toward_the_next_collection_threshold() {
        let big = ts_rt_arr_new(200_000, 0);
        unsafe { (*big).len = 200_000 };
        let h = ts_rt_root_add(big as *mut u8);
        ts_rt_gc_collect();
        // 1.6 MB of numbers are alive; collecting again after only 512 KiB would be thrashing.
        assert!(
            gc_stats().next_collection_at >= 1_600_000,
            "{:?}",
            gc_stats()
        );
        ts_rt_root_remove(h);
    }

    // M9-TS-33
    #[test]
    fn two_different_structs_with_one_id_are_refused() {
        assert!(register_struct(7, 2, 0b10).is_ok());
        assert!(
            register_struct(7, 2, 0b10).is_ok(),
            "the same table again is fine"
        );
        let e = register_struct(7, 3, 0b01).unwrap_err();
        assert!(e.contains("collides"), "{e}");
    }

    // M9-TS-109
    //
    // The comparator of `sort` is script code that can collect. The merge buffer and the closure
    // are held by the sort alone; poisoned (freed) elements show up as wrong lengths.
    #[test]
    fn sort_keeps_its_merge_buffer_alive_while_the_comparator_collects() {
        extern "C" fn by_len(_env: *mut u8, a: u64, b: u64) -> f64 {
            ts_rt_gc_collect();
            // SAFETY: both are arrays.
            unsafe { (*(a as *mut Array)).len as f64 - (*(b as *mut Array)).len as f64 }
        }
        ts_rt_gc_stress(true);
        let list = ts_rt_arr_new(0, 1);
        ts_rt_root_add(list as *mut u8);
        let lens = [5u32, 3, 8, 1, 9, 2, 7, 4, 6, 0, 5, 3];
        for n in lens {
            let e = ts_rt_arr_new(0, 0);
            for k in 0..n {
                // SAFETY: `e` is an array.
                unsafe { ts_rt_arr_push(e, k as u64) };
            }
            // SAFETY: `list` is an array.
            unsafe { ts_rt_arr_push(list, e as u64) };
        }
        let cmp = ts_rt_closure_new(by_len as *const u8, std::ptr::null_mut());
        // SAFETY: a pointer array and a comparator of two pointers.
        unsafe { ts_rt_arr_sort(list, cmp, 1) };
        ts_rt_gc_stress(false);
        let got: Vec<i64> = (0..lens.len())
            // SAFETY: elements are arrays kept alive by the sort.
            .map(|i| unsafe { (*(*list).get::<*mut Array>(i)).len })
            .collect();
        let mut want: Vec<i64> = lens.iter().map(|n| *n as i64).collect();
        want.sort();
        assert_eq!(got, want);
    }
}
